// stderrTail renders what the process said on stderr as a suffix for a
// failure message, and nothing at all when it said nothing.
func stderrTail(text string) string {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return ""
	}

	return ": " + trimmed
}

